entries[61241] = { ["name"] = "Heroic Leap", ["text"] = "5 - 45 yd range\nInstant 45 sec cooldown\nLeap through the air and slam down on all enemies within 8 yards of the target area, causing 1% weapon damage and stunning them for 0.10 sec." }
