entries[61247] = { ["name"] = "Intravenous Healing Potion", ["text"] = "5 yd range\n3 sec cast\nSet up an Intravenous Healing Potion for your party. Restores 15001 health and ( 2160 / 5 * 30) mana over 30 sec. Cannot be used in combat." }
entries[61248] = { ["name"] = "Power of Tenebron", ["text"] = "Unlimited range\nInstant\nTenebron's presence increases Shadow damage taken by all enemies by 100%." }
