entries[61254] = { ["name"] = "Will of Sartharion", ["text"] = "Unlimited range\nInstant\nSartharion's presence bolsters the resolve of the Twilight Drakes, increasing their total health by 25%. This effect also increases Sartharion's health by 25%." }
entries[61255] = { ["name"] = "Trap Cooldown Reduction", ["text"] = "Reduces the cooldown of your Traps and Black Arrow by 2 seconds." }
entries[61256] = { ["name"] = "Increased Focus Regeneration", ["text"] = "Increases the regeneration of your Focus by 25%." }
entries[61257] = { ["name"] = "Runic Power Back on Snare/Root", ["text"] = "Runic Power Back on Snare/Root\nWhenever you are struck by a movement-impairing effect, you will generate 3 Runic Power every 1 sec for 5 sec." }
